/*
 * bsp_platform_config.c
 *
 * CM7_2 binding between common BSP logic and symbols generated by this
 * image's S32 Configuration Tools project.
 */

#include "app_core.h"
#include "bsp_core.h"
#include "bsp_timebase.h"

#include "IntCtrl_Ip_Cfg.h"
#include "Stm_Ip_Cfg.h"
#include "Stm_Ip_SA_PBcfg.h"

#define BSP_STM_10MS_TICKS       (10000U)
#define BSP_STM_100MS_TICKS      (100000U)
#define BSP_STM_1000MS_TICKS     (1000000U)

static const BspCoreConfigType s_BspCoreConfig =
{
    APP_CORE_SECONDARY_PHYSICAL_ID,
    &IntCtrlConfig_2
};

static const BspTimebaseConfigType s_BspTimebaseConfig =
{
    STM_2_IP_INSTANCE_NUMBER,
    &STM_2_InitConfig_PB,
    {
        { STM_2_CH_0, 0U, BSP_STM_10MS_TICKS },
        { STM_2_CH_1, 1U, BSP_STM_100MS_TICKS },
        { STM_2_CH_2, 2U, BSP_STM_1000MS_TICKS }
    }
};

const BspCoreConfigType *BspCore_GetConfig(void)
{
    return &s_BspCoreConfig;
}

const BspTimebaseConfigType *BspTimebase_GetConfig(void)
{
    return &s_BspTimebaseConfig;
}
